    float EL = clamp(dot(mc.eye_dir, light_param.direction), 0.0, 1.0);
    EL = (EL * EL);
    EL = (EL * EL);
    float NL = clamp(dot((-mc.normal), light_param.direction), 0.0, 1.0);
    mc.diffuse2 += (light_param.diffuse_back * EL);
    mc.diffuse3 += (light_param.diffuse_back * NL);
  }
  return mc;
}

