createMaterialContext.glsl:
MATERIAL_CONTEXT createMaterialContext(MATERIAL_OUTPUT I, bool isfrontface) {
  I.wnormal = FFrontFaceNormal(I.wnormal, isfrontface);
  float ln = max(9.999999974752427e-07, sqrt(dot(I.wnormal, I.wnormal)));
  float lt = max(9.999999974752427e-07, sqrt(dot(I.wtangent, I.wtangent)));
  float lb = max(9.999999974752427e-07, sqrt(dot(I.wbinormal, I.wbinormal)));
  MATERIAL_CONTEXT mc = initMaterialContext(I.position, I.wposition, (I.wnormal / ln), (I.wtangent / lt), (I.wbinormal / lb), I.uv_primary, I.uv_secondary, I.uv_unique, I.uv_extend);
  mc.occlusion = I.occlusion;
  mc.vertex_color = I.vcolor.xyz;
  mc.transparency = I.vcolor.w;
  mc.attributes = I.attributes;
  mc = FDefaultTransparency(mc);
  return mc;
}

initMaterialContext.glsl:
MATERIAL_CONTEXT initMaterialContext(vec4 svposition, vec3 wposition, vec3 normal, vec3 tangent, vec3 binormal, vec2 uv_primary, vec2 uv_secondary, vec2 uv_unique, vec2 uv_extend) {
  MATERIAL_CONTEXT mc = zero_MATERIAL_CONTEXT();
  mc.svposition = svposition;
  mc.wposition = wposition;
  mc.normal = normal;
  mc.vertex_normal = normal;
  mc.tangent = tangent;
  mc.binormal = binormal;
  mc.uv_primary = uv_primary;
  mc.uv_secondary = uv_secondary;
  mc.uv_unique = uv_unique;
  mc.uv_extend = uv_extend;
  mc.eye_dir = normalize((wposition - CBViewProjection_fCameraPos));
  mc.reflect_dir = reflect(mc.eye_dir, normal);
  mc.albedo = vec3(float(1));
  mc.shininess = float(1);
  mc.transparency = float(1);
  mc.ambient_occlusion = float(1);
  mc.occlusion = float(1);
  mc.fresnel = float(1);
  mc.uv_screen = (svposition.xy * CBScreen_fScreenInverseSize);
  mc.global_transparency = float(1);
  mc.tangent_primary = tangent;
  mc.tangent_secondary = tangent;
  return mc;
}

FFrontFaceNormal.glsl:
vec3 FFrontFaceNormal(vec3 normal, bool isfrontface) {
  if ((!isfrontface)) {
    normal *= float((-1));
  }
  return normal;
}

VS_MaterialStd.glsl:
MATERIAL_OUTPUT VS_MaterialStd(MATERIAL_INPUT I, SWING_INPUT SWI, MORPH_INPUT MI, SOFTBODY_INPUT SI, LATTICE_DEFORM_INPUT LDI, INSTANCING_INPUT ISI, PROJECTION_INPUT VPI, int instance_id) {
  MATERIAL_OUTPUT O = zero_MATERIAL_OUTPUT();
  vec3 wpos = vec3(float(0), float(0), float(0));
  vec3 wn = vec3(float(0), float(0), float(0));
  vec3 wt = vec3(float(0), float(0), float(0));
  vec3 wb = vec3(float(0), float(0), float(0));
  WORLD_COORDINATE_INPUT W = zero_WORLD_COORDINATE_INPUT();
  W.position = I.position;
  W.normal = I.normal;
  W.tangent = I.tangent;
  W.weights = I.weights;
  W.joints = I.joints;
  W.SWI = SWI;
  W.MI = MI;
  W.SI = SI;
  W.LDI = LDI;
  W.ISI = ISI;
  W.VPI = VPI;
  W.instance_id = instance_id;
  FWorldCoordinate(wpos, wn, wt, wb, W);
  FVertexDisplacement(wpos, wn, wt, wb, I.uv_primary, I.uv_secondary, I.uv_unique, I.uv_extend, I.tangent.w, I.occlusion);
  O.position = FViewProj(wpos, I.uv_unique);
  O.wnormal = normalize(wn);
  O.wtangent = wt;
  O.wbinormal = wb;
  O.wposition = wpos;
  O.uv_primary = FUVTransformPrimary(I.uv_primary);
  O.uv_secondary = FUVTransformSecondary(I.uv_secondary);
  O.uv_unique = FUVTransformUnique(I.uv_unique);
  O.uv_extend = FUVTransformExtend(I.uv_extend);
  O.vcolor = (vec4(FLinearColor(I.vcolor), I.valpha) * ISI.instance_color);
  O.occlusion = I.occlusion;
  O.attributes = FShaderAttributes(W);
  return O;
}

