FWorldCoordinate.glsl:
void FWorldCoordinate(out vec3 wpos, out vec3 wn, out vec3 wt, out vec3 wb, WORLD_COORDINATE_INPUT param) {
  FMorph(param);
  mat3x4 wmat = FWorldMatrix(param);
  wpos = (vec4(param.position, float(1)) * wmat);
  wn = (vec4(param.normal, float(0)) * wmat);
  wt = (vec4(param.tangent.xyz, float(0)) * wmat);
  FInstancing(wpos, wn, wt, param.ISI);
  wb = (cross(wt, wn) * param.tangent.w);
}

