mat3x4 FWorldMatrix(WORLD_COORDINATE_INPUT param) {
  SKINNING_INPUT in_skin = zero_SKINNING_INPUT();
  in_skin.weights = param.weights;
  in_skin.joints = param.joints;
  return FSkinning(in_skin);
}

